/**
 * Frozen shared contracts for the prime_agent_local adapter (WP0).
 *
 * Every work package codes against these types. Workers do not edit this file
 * or INTERFACES.md; a needed change goes back to the parent. Behaviour, owners,
 * error cases and open points for each item are in INTERFACES.md.
 */
import type {
  AdapterBillingType,
  AdapterModel,
} from "@paperclipai/adapter-utils";

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

export const PRIME_ADAPTER_TYPE = "prime_agent_local";
export const PRIME_ADAPTER_LABEL = "Prime Agent";
export const PRIME_DEFAULT_COMMAND = "prime-agent";

/** Supported `prime-agent --version` range: min inclusive, max exclusive. */
export const PRIME_SUPPORTED_VERSION_RANGE = { min: "0.10.0", maxExclusive: "0.11.0" } as const;

// ---------------------------------------------------------------------------
// Runtime config (WP1, src/server/runtime-config.ts)
// ---------------------------------------------------------------------------

export const PRIME_THINKING_LEVELS = ["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const;
export type PrimeThinkingLevel = (typeof PRIME_THINKING_LEVELS)[number];

export type PrimeCredentialMode = "host_auth" | "api_key" | "managed_subscription";

/** Where the per-agent Prime dir gets its provider credential from. */
export type PrimeCredentialConfig =
  | {
      mode: "host_auth";
      /** Absolute path of the host Prime auth file. Default `<os.homedir()>/.prime/agent/auth.json`. */
      hostAuthFile: string;
    }
  | {
      mode: "api_key";
      /** Provider key written into the per-agent auth.json; equals PrimeRuntimeConfig.provider. */
      provider: string;
      /** Name of the config env var that holds the key (for example ANTHROPIC_API_KEY). Never the value. */
      apiKeyEnvVar: string;
    }
  | {
      /** TAI-273 §3 (C1): the host's managed Claude subscription. The token comes from env CLAUDE_CODE_OAUTH_TOKEN. */
      mode: "managed_subscription";
      /** Always "anthropic"; equals PrimeRuntimeConfig.provider. */
      provider: string;
    };

/** Paths for one Prime agent dir. Pure data; creating it is seedPrimeAgentDir's job. */
export interface PrimeAgentDirPlan {
  /** "agent": durable per-agent dir. "ephemeral": temp dir for probes (testEnvironment, listModels). */
  kind: "agent" | "ephemeral";
  /** Absolute. Exported to the child as PRIME_AGENT_CODING_AGENT_DIR. */
  agentDir: string;
  /** Absolute. `<agentDir>/sessions`. Passed as `--session-dir`. */
  sessionDir: string;
  credential: PrimeCredentialConfig;
}

/** Resolved adapterConfig for one agent. Contains no secret values. */
export interface PrimeRuntimeConfig {
  /** config.command, default "prime-agent". */
  command: string;
  /** config.model exactly as configured (trimmed), `provider/modelId`. */
  modelRef: string;
  /** Part of modelRef before the first "/". */
  provider: string;
  /** Part of modelRef after the first "/" (may itself contain "/", e.g. vercel-ai-gateway ids). */
  model: string;
  /** config.thinking; null means the flag is not passed. */
  thinking: PrimeThinkingLevel | null;
  /** config.cwd as an absolute path, or null. Fallback only; execute prefers the Paperclip workspace cwd. */
  cwd: string | null;
  /** config.instructionsFilePath (instructions bundle), or null. */
  instructionsFilePath: string | null;
  /** config.promptTemplate, or null (execute then uses the Paperclip default templates). */
  promptTemplate: string | null;
  /** config.bootstrapPromptTemplate, or null. */
  bootstrapPromptTemplate: string | null;
  /** config.appendSystemPrompt, or null. Passed as an extra `--append-system-prompt`. */
  appendSystemPrompt: string | null;
  /** config.noContextFiles, default false. true adds `--no-context-files`. */
  noContextFiles: boolean;
  /** config.timeoutSec, default 0 (no timeout, as pi-local). */
  timeoutSec: number;
  /** config.graceSec, default 20 (as pi-local). */
  graceSec: number;
  /** config.extraArgs, else config.args (as pi-local); string array. */
  extraArgs: string[];
  /** String-valued entries of config.env (secret bindings arrive resolved). */
  env: Record<string, string>;
  credential: PrimeCredentialConfig;
  agentDir: PrimeAgentDirPlan;
}

/** Minimal agent identity needed to resolve config. */
export interface PrimeAgentIdentity {
  id: string;
  companyId: string;
}

export type ResolvePrimeRuntimeConfig = (
  config: Record<string, unknown>,
  agent: PrimeAgentIdentity,
  /** `<PAPERCLIP_HOME>/instances/<instanceId>`, from resolvePaperclipInstanceRootForAdapter(). */
  instanceRoot: string,
) => PrimeRuntimeConfig;

export interface SeededPrimeAgentDir {
  plan: PrimeAgentDirPlan;
  /** How auth.json was provisioned in this dir. */
  auth: "host_auth_symlink" | "api_key_file" | "managed_token_file";
  /** "subscription" for a host OAuth credential or an `sk-ant-oat` subscription token; "api" for other API keys; "unknown" otherwise. */
  billingType: Extract<AdapterBillingType, "subscription" | "api" | "unknown">;
  /** Human-readable notes for onMeta commandNotes. Never contain secrets. */
  notes: string[];
}

export type SeedPrimeAgentDir = (
  plan: PrimeAgentDirPlan,
  input: {
    /** Provider of the configured model; selects the auth.json entry to classify or write. "" when unknown (model listing). */
    provider: string;
    /** Run env after config merge; api_key mode reads `env[apiKeyEnvVar]` from here. */
    env: Record<string, string>;
  },
) => Promise<SeededPrimeAgentDir>;

/** Created but not seeded; callers run seedPrimeAgentDir on `plan`. */
export interface EphemeralPrimeAgentDir {
  plan: PrimeAgentDirPlan;
  /** Removes the temp dir. Never throws. */
  cleanup: () => Promise<void>;
}

export type CreateEphemeralPrimeAgentDir = (credential: PrimeCredentialConfig) => Promise<EphemeralPrimeAgentDir>;

// ---------------------------------------------------------------------------
// Child environment (WP1, src/server/runtime-config.ts)
// ---------------------------------------------------------------------------

/** Keys the adapter owns; dropped from config/Paperclip env too, then set by the adapter or left unset. */
export const PRIME_ADAPTER_OWNED_ENV_KEYS = [
  "PRIME_AGENT_CODING_AGENT_DIR",
  "PRIME_AGENT_SESSION_DIR",
  "PRIME_AGENT_TELEMETRY",
  "PRIME_AGENT_DAEMON_SOCKET",
  "PRIME_AGENT_KERNEL_OWNER_PID",
] as const;

/** Prefixes dropped from config/Paperclip env as well as from the base env. */
export const PRIME_ALWAYS_STRIPPED_ENV_PREFIXES = ["PRIME_AGENT_INTERNAL_", "RLM_", "PI_"] as const;


export interface PrimeChildEnv {
  /** A8: stripped keys are present with value `undefined` so runChildProcess deletes them after its own process.env merge. */
  env: Record<string, string | undefined>;
  /** Names (never values) of keys removed from base or Paperclip env. */
  droppedKeys: string[];
}

export type BuildPrimeChildEnv = (
  /** Usually process.env of the Paperclip server. */
  base: NodeJS.ProcessEnv,
  plan: PrimeAgentDirPlan,
  /** buildPaperclipEnv + run vars + refreshPaperclipWorkspaceEnvForExecution output (includes config.env). */
  paperclipEnv: Record<string, string>,
  /** stripAnthropicEnv: drop every ANTHROPIC_* key of paperclipEnv (TAI-273 §3.2: managed_subscription, and api_key under governed-v1). */
  options?: { stripAnthropicEnv?: boolean },
) => PrimeChildEnv;

// ---------------------------------------------------------------------------
// Arguments (WP3, src/server/execute.ts)
// ---------------------------------------------------------------------------

export interface PrimeArgsInput {
  provider: string;
  model: string;
  thinking: PrimeThinkingLevel | null;
  /** Absolute execution cwd. */
  cwd: string;
  /** PrimeAgentDirPlan.sessionDir. */
  sessionDir: string;
  /** Absolute session file to resume (`-r`), or null for a fresh session. */
  resumeSessionFile: string | null;
  /** Staged skill dirs, one `--skill` each, in order. */
  skillDirs: string[];
  /** Each entry becomes one `--append-system-prompt <text>`, in order. Empty strings are skipped. */
  appendSystemPrompts: string[];
  noContextFiles: boolean;
  extraArgs: string[];
  /** User prompt; always the last argv element, after `--`. */
  prompt: string;
}

export type BuildPrimeArgs = (input: PrimeArgsInput) => string[];

// ---------------------------------------------------------------------------
// Output parsing (WP2, src/server/parse.ts)
// ---------------------------------------------------------------------------

export interface PrimeUsage {
  /** Sum of usage.input over assistant turn_end messages. */
  inputTokens: number;
  /** Sum of usage.output. */
  outputTokens: number;
  /** Sum of usage.cacheRead. */
  cachedInputTokens: number;
  /** Sum of usage.cacheWrite (not in Paperclip UsageSummary; goes to resultJson). */
  cacheWriteTokens: number;
  /** Sum of usage.totalTokens. */
  totalTokens: number;
  /** Sum of usage.cost.total in USD as reported by Prime (0 on subscription runs). */
  reportedCostUsd: number;
}

export interface PrimeToolCall {
  toolCallId: string;
  toolName: string;
  args: unknown;
  /** Text of the result content, or JSON of the raw result; null until tool_execution_end. */
  result: string | null;
  isError: boolean;
}

export interface ParsedPrimeOutput {
  /** `id` of the first `session` event. */
  sessionId: string | null;
  /** `cwd` of the first `session` event. */
  sessionCwd: string | null;
  /** Text of each assistant turn_end message that has text, in order. */
  messages: string[];
  /** Text of the last assistant message in agent_end (else the last turn_end text). */
  finalMessage: string | null;
  /** Provider failures and error events, deduplicated, in order. */
  errors: string[];
  /** stopReason of the last assistant message ("stop", "toolUse", "error", "aborted", ...). */
  lastStopReason: string | null;
  /** provider/model reported by the last assistant message. */
  provider: string | null;
  model: string | null;
  /** null when no assistant usage was seen; never zero-filled. */
  usage: PrimeUsage | null;
  toolCalls: PrimeToolCall[];
  /** true when an `agent_end` event was seen. false means the run outcome is uncertain. */
  sawAgentEnd: boolean;
}

export type ParsePrimeJsonl = (stdout: string) => ParsedPrimeOutput;
export type IsPrimeUnknownSessionError = (stdout: string, stderr: string) => boolean;

// ---------------------------------------------------------------------------
// Session (WP4, src/server/session.ts)
// ---------------------------------------------------------------------------

export interface PrimeSessionParams {
  /** Prime session id (session event `id`). */
  sessionId: string;
  /** Absolute path `<sessionDir>/<sessionId>.jsonl`. */
  sessionFile: string;
  /** Execution cwd the session was created in. */
  cwd: string;
  provider: string;
  model: string;
  /** PRIME_AGENT_CODING_AGENT_DIR the session belongs to. */
  agentDir: string;
}

/** Host metadata keys Paperclip mixes into stored session params; the codec ignores exactly these. */
export const HOST_SESSION_METADATA_KEYS = ["paperclipAiCredentialIdentity", "__paperclipConfiguredModel"] as const;
/** Host metadata key prefixes the codec ignores. */
export const HOST_SESSION_METADATA_KEY_PREFIXES = ["__paperclipConfigFingerprint", "__paperclipConfigCategor"] as const;

export interface PrimeSessionHeader {
  id: string;
  cwd: string | null;
}

export type ReadPrimeSessionHeader = (sessionFile: string) => Promise<PrimeSessionHeader | null>;

export type PrimeResumeDecision =
  | { resume: true; sessionFile: string }
  | {
      resume: false;
      reason:
        | "no_saved_session"
        | "cwd_mismatch"
        | "model_mismatch"
        | "agent_dir_mismatch"
        | "session_file_missing"
        | "session_header_mismatch";
    };

export type DecidePrimeResume = (input: {
  saved: PrimeSessionParams | null;
  current: { cwd: string; provider: string; model: string; agentDir: string };
  /** Header read from saved.sessionFile, or null when unreadable/missing. */
  header: PrimeSessionHeader | null;
}) => PrimeResumeDecision;

// ---------------------------------------------------------------------------
// Models and version (WP4 src/server/models.ts, WP5 src/server/version.ts)
// ---------------------------------------------------------------------------

export interface PrimeModelRow {
  provider: string;
  model: string;
  /** `provider/model`. */
  id: string;
  context: string;
  maxOut: string;
  thinking: boolean;
  images: boolean;
}

export type ParsePrimeModelList = (stdout: string) => PrimeModelRow[];

export type ListPrimeModels = (input: {
  command: string;
  /** Child env; MUST set PRIME_AGENT_CODING_AGENT_DIR (model list writes auth.json and models/ there). A8: pass to runChildProcess unchanged, undefined entries included. */
  env: Record<string, string | undefined>;
  cwd: string;
}) => Promise<AdapterModel[]>;

export type DetectPrimeModel = (agentDir: string) => Promise<{
  model: string;
  provider: string;
  source: string;
} | null>;

export type ReadPrimeVersion = (input: {
  command: string;
  /** A8: pass to runChildProcess unchanged, undefined entries included. */
  env: Record<string, string | undefined>;
  cwd: string;
}) => Promise<string>;

export type IsSupportedPrimeVersion = (version: string) => boolean;

// ---------------------------------------------------------------------------
// Skills (WP4, src/server/skills.ts)
// ---------------------------------------------------------------------------

export interface StagedPrimeSkills {
  /** Absolute dirs to pass as `--skill`, one per desired, present skill. */
  skillDirs: string[];
  /** Runtime names that were desired but missing on disk (logged, not fatal). */
  missing: string[];
  /** TAI-273 §4.1 (G1): one `[paperclip]` line per skill staged under its runtime name instead of its frontmatter name. */
  logLines: string[];
  /** Removes the temp dir. Never throws. */
  cleanup: () => Promise<void>;
}

export type StagePrimeSkills = (config: Record<string, unknown>) => Promise<StagedPrimeSkills>;

