export const PRIME_CHECK_CODES = [
  "prime_cwd_valid",
  "prime_cwd_invalid",
  "prime_cli_found",
  "prime_cli_missing",
  "prime_cli_version",
  "prime_cli_version_unsupported",
  "prime_cli_version_unreadable",
  "prime_config_invalid",
  "prime_model_required",
  "prime_model_invalid",
  "prime_thinking_invalid",
  "prime_auth_host_linked",
  "prime_auth_api_key",
  "prime_auth_missing",
  "prime_auth_unsafe",
  "prime_models_discovered",
  "prime_models_empty",
  "prime_models_discovery_failed",
  /** host_auth: the host login is never linked into a temp dir (TAI-225 §9 item 8), so the environment test lists no models. */
  "prime_models_skipped",
  "prime_model_listed",
  "prime_model_unknown",
  /** TAI-273 §3.2: the load-time registration of prime_agent_local for the anthropic subscription method. */
  "prime_auth_managed_registered",
  "prime_auth_managed_unregistered",
  /** TAI-273 §3.2 checks 1-3 passed on the token the test body carried. */
  "prime_auth_managed_token_ok",
  /** TAI-273 §3.2: a fail-closed rule or a check 1-4 failed. */
  "prime_managed_connection_invalid",
] as const;
export type PrimeCheckCode = (typeof PRIME_CHECK_CODES)[number];

// ---------------------------------------------------------------------------
// Execution result error codes (WP3)
// ---------------------------------------------------------------------------

export const PRIME_RESULT_ERROR_CODES = [
  /** Failure before spawn (config, credentials, version, model, skills). clearSession: false. */
  "prime_preflight_failed",
  /** Prime exited or reported an error (assistant stopReason "error", non-zero exit). */
  "prime_run_failed",
  /** Process ended without an agent_end event (killed, crashed, lost). Session kept. */
  "prime_run_uncertain",
  /** Timed out (timedOut: true). */
  "prime_run_timeout",
  /** Cancelled via ctx.signal before or during the run. */
  "prime_run_cancelled",
  /** TAI-225 §9 policy codes (PrimePolicyErrorCode in errors.ts). After a run they replace the run's own code, which moves to errorMeta.runErrorCode. */
  "prime_settings_invalid",
  "prime_allowed_models_invalid",
  "prime_settings_tampered",
  "prime_auth_tampered",
  "prime_model_audit_failed",
  /** TAI-273 §3.2: a Paperclip AI binding without managed_subscription, or managed_subscription whose checks fail. Before any file is written. */
  "prime_managed_connection_invalid",
  /** TAI-273 §3.2: auth.json could not be deleted after a managed_subscription run. */
  "prime_auth_cleanup_failed",
  /** TAI-273 §3.2: the provider refused the credential (diagnostic kind "auth"). The session row is kept. */
  "prime_provider_auth_failed",
  /** TAI-273 §3.2: the provider rate limit or usage limit (diagnostic kind "rate_limit", after Prime's retries). The session row is kept. */
  "prime_provider_quota",
  /** TAI-273 §2.2: featureProfile is invalid, or its rules fail. Before any file is written. */
  "prime_feature_profile_invalid",
  /** TAI-273 §2.2 item 2: a session over maxSubagentsPerRun could not be ended, or an ended session ran again. */
  "prime_subagent_limit_exceeded",
  /** TAI-273 §4.3 item 2: the saved session's lease is held by another Prime process. No session fields, no clearSession. */
  "prime_session_busy",
  /** TAI-273 §2.2 item 10: the parent's skill list is wrong (before any prompt), or a session ended for its skills could not be ended or ran again. */
  "prime_skill_list_invalid",
  /** TAI-273 §2.2 item 12: the model-catalog check or the parent's thinking level failed. Before the first prompt: no session fields, no clearSession. */
  "prime_model_catalog_invalid",
] as const;
export type PrimeResultErrorCode = (typeof PRIME_RESULT_ERROR_CODES)[number];
